import {hostPublications} from './publications.js';
import {clusterType,clusterConnections,networkRuntime} from './workloads.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,key,v,type='text')=>`<label>${label}<input data-key="${key}" type="${type}" value="${esc(v)}"></label>`;
const select=(label,key,v,options)=>`<label>${label}<select data-key="${key}">${options.map(([id,name])=>`<option value="${esc(id)}" ${v===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
export function workloadHTML(s,n){let h='';const kind=clusterType(n);
 if(kind)h+=`<div class="section">ЧЛЕНСТВО В КЛАСТЕРЕ</div><label>Кластер<select data-cluster><option value="">Без кластера</option>${s.nodes.filter(c=>c.type===kind).map(c=>`<option value="${esc(c.id)}" ${c.id===n.clusterId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p>Создайте кластер через «＋ Объект» на верхнем уровне. Пунктирные связи показывают членство; кабели подключаются отдельно.</p>`;
 if(['k8s_cluster','proxmox_cluster'].includes(n.type)){const members=clusterConnections(s).filter(e=>e.cluster.id===n.id);h+=`<div class="section">УЧАСТНИКИ · ${members.length}</div>${members.map(e=>`<div class="hint">${esc(e.member.name)}${e.member.services.kubernetes?' · '+esc(e.member.services.kubernetes.role):''}</div>`).join('')||'<p>Выберите Proxmox VE или узел Kubernetes и укажите этот кластер в его свойствах.</p>'}<p>Логическая группа. Quorum, Corosync, API, etcd и автоматическое планирование в прототипе не эмулируются.</p>`}
 if(n.services.runtime){const r=n.services.runtime;h+=`<div class="section">КОНТЕЙНЕР · СРЕДА ВЫПОЛНЕНИЯ</div>${field('Образ','runtime.image',r.image)}${select('Состояние','runtime.status',r.status,[['running','Запущен'],['stopped','Остановлен']])}${field('Команда / entrypoint','runtime.command',r.command)}${field('Политика перезапуска','runtime.restart',r.restart)}${field('CPU, ядер (описание)','runtime.cpu',r.cpu)}${field('Память (описание)','runtime.memory',r.memory)}${field('Переменные окружения KEY=VALUE','runtime.environment',r.environment)}${field('Тома host:container','runtime.volumes',r.volumes)}<p>Сеть: ${n.type==='k8s_container'?'общий namespace Pod; NIC и IP на Pod. Это контейнер, не Docker Engine. Им управляет CRI runtime узла (в демо containerd)':'bridge; интерфейсы и veth подключаются явно'}. Образ, ресурсы, тома и команда сохраняются как параметры схемы. Запуск реальных процессов не выполняется.</p>`}
 if(n.type==='application'){const host=networkRuntime(s,n);h+=`<div class="section">ПРИЛОЖЕНИЕ · HTTP</div>${field('Команда запуска','process.command',n.services.process?.command||'')}${field('TCP-порт','http.port',n.services.http.port,'number')}${select('Служба','http.enabled',String(n.services.http.enabled!==false),[['true','Включена'],['false','Выключена']])}<p>Слушает на интерфейсах ${esc(host?.name||'среды выполнения')}. Собственный кабель не требуется: процесс использует сетевой namespace среды. ${host?.type==='container'?'Публикация внешнего порта настраивается у Docker контейнера.':host?.type==='pod'?'Доступ по IP Pod требует сетевого пути. Для доступа снаружи создайте NodePort Service в кластере; Ingress пока не моделируется.':'Для прямого доступа используйте IP ОС и порт приложения.'}</p>`}
 if(n.type==='k8s_node'){const k=n.services.kubernetes;h+=`<div class="section">KUBERNETES NODE</div>${select('Роль','kubernetes.role',k.role,(s.nodes.find(p=>p.id===n.parent)?.type==='windows'?[['worker','Worker']]:[['worker','Worker'],['control-plane','Control plane']]))}${field('Версия Kubernetes','kubernetes.version',k.version)}${field('CNI (описание)','kubernetes.cni',k.cni)}${field('Pod CIDR (описание)','kubernetes.podCIDR',k.podCIDR)}<p><b>Node — это родительская Ubuntu-ВМ целиком.</b> Внутри отдельно показаны kubelet и containerd; эта рамка группирует службы управления и управляемые Pod; она не является второй ОС, коммутатором или сетевым namespace. eth0, cni0, маршруты и veth хостового конца находятся в ядре Ubuntu. cni0 используется в выбранной bridge/routed CNI-модели; другие CNI могут работать иначе.</p>`}
 if(n.type==='k8s_service'){const p=n.services.nodeport,publications=s.nodes.flatMap(host=>hostPublications(s,host)).filter(a=>a.entity?.id===n.id),pods=[...new Map(publications.flatMap(p=>p.candidates).map(c=>[c.pod.id,c])).values()];h+=`<div class="section">SERVICE · TCP NODEPORT</div>${select('Политика внешнего трафика','nodeport.externalTrafficPolicy',p.externalTrafficPolicy,[['Local','Local · только локальный Pod'],['Cluster','Cluster · любой готовый Pod']])}${field('Namespace','nodeport.namespace',p.namespace)}${field('Selector · key=value','nodeport.selector',p.selector)}${field('Порт Service (метаданные)','nodeport.port',p.port,'number')}${field('Целевой порт приложения','nodeport.targetPort',p.targetPort,'number')}${field('NodePort · 30000–32767','nodeport.nodePort',p.nodePort,'number')}<label>Предпочтительный Pod · выбор для демонстрации<select data-key="nodeport.preferredPod"><option value="">Первый готовый endpoint</option>${pods.map(c=>`<option value="${esc(c.pod.id)}" ${p.preferredPod===c.pod.id?'selected':''}>${esc(c.pod.name)} · ${c.ready?'Ready':esc(c.reason)}</option>`).join('')}</select></label><button data-fail-endpoint="${n.id}">Отказать выбранному Pod</button><button data-restore-endpoints="${n.id}">Восстановить готовность Pod</button><p>Новый запрос после отказа исключает NotReady endpoint и выбирает другую реплику. Установленный TCP-поток не мигрирует. Выбор предпочтительного Pod детерминирован для демонстрации. Cluster: DNAT + MASQUERADE/SNAT, маршруты CNI ведут на другой worker через физическую LAN. Local: kube-proxy направляет запрос в готовый Pod на этом же узле. Исходный IP клиента сохраняется. Если локального endpoint нет, запрос останавливается. ClusterIP и Ingress не моделируются.</p>`}
 if(n.type==='pod'){const p=n.services.pod;h+=`<div class="section">POD · ОБЩАЯ СЕТЬ</div>${field('Namespace','pod.namespace',p.namespace)}${field('Labels','pod.labels',p.labels)}${select('Готовность endpoint','pod.ready',String(p.ready!==false),[['true','Ready'],['false','NotReady · исключить из Service']])}${select('Состояние','pod.status',p.status,[['running','Запущен'],['stopped','Остановлен']])}<p>Контейнеры этого Pod используют один IP и общий набор портов. Создайте внутри «Контейнер Pod», затем «Приложение».</p>`}
 if(n.services.cni){h+='<div class="section">ЯДРО ОС · ROUTED CNI / HOST-GW</div><p>Node = эта ОС. eth0 и cni0 не соединены кабелем: между ними IP-маршрутизация. Сеть Pod принадлежит ядру Ubuntu; kubelet и containerd только управляют Pod.</p>'+select('Пересылка CNI','cni.enabled',String(n.services.cni.enabled),[['true','Включена'],['false','Выключена']])+field('Маршруты · CIDR=next-hop (через запятую)','cni.routes',n.services.cni.routes.map(r=>r.cidr+'='+r.via).join(', '))}return h;
}
export {clusterWires} from './cluster-wires.js';
export function workloadFoot(s,n){if(n.type==='containerd')return 'УПРАВЛЕНИЕ · CRI server / Unix socket';if(n.type==='kubelet')return 'УПРАВЛЕНИЕ · CRI client';if(n.type==='k8s_node'){const host=s.nodes.find(p=>p.id===n.parent);return 'Node = '+esc(host?.name||'родительская ОС')+' · kubelet / '+esc(n.services.kubernetes.runtime)}if(n.clusterId){const c=s.nodes.find(c=>c.id===n.clusterId);return '⛓ '+esc(c?.name||'Кластер')+(n.services.kubernetes?' · '+esc(n.services.kubernetes.role):'')}if(['k8s_cluster','proxmox_cluster'].includes(n.type))return '⛓ Логический кластер · '+clusterConnections(s).filter(e=>e.cluster.id===n.id).length+' узлов';if(n.type==='k8s_service')return 'NodePort :'+esc(n.services.nodeport.nodePort)+' → Pod :'+esc(n.services.nodeport.targetPort)+' · '+esc(n.services.nodeport.externalTrafficPolicy);if(n.type==='k8s_container'){const pod=s.nodes.find(p=>p.id===n.parent),node=s.nodes.find(p=>p.id===pod?.parent);return esc(n.services.runtime.image)+' · runtime: '+esc(node?.services.kubernetes?.runtime||'CRI runtime')+' · '+(n.services.runtime.status==='stopped'?'остановлен':'запущен')}if(n.services.runtime)return esc(n.services.runtime.image)+' · '+(n.services.runtime.status==='stopped'?'остановлен':'запущен');if(n.type==='application')return 'HTTP :'+esc(n.services.http.port)+' · '+(n.services.http.enabled===false?'выключен':'включён');if(n.type==='pod')return 'Общий namespace сети · '+esc(n.services.pod.namespace);return ''}
